"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[717],{8948:e=>{e.exports=JSON.parse('{"functions":[{"name":"event","desc":"Creates an [Event], a typed `RemoteEvent`. Arguments are checked against the GreenTea types on both sides.\\n\\n```lua\\ndamageEvent = Sencha.event(gt.number(), gt.Vector3()),\\n```","params":[{"name":"...","desc":"the type of each argument","lua_type":"GreenTeaType"}],"returns":[{"desc":"","lua_type":"Event<T...>"}],"function_type":"static","source":{"line":102,"path":"src/init.luau"}},{"name":"unreliableEvent","desc":"Creates an [Event] backed by an `UnreliableRemoteEvent`. It has the same API as [Sencha.event], but messages\\nmay be dropped or arrive out of order, and payloads are limited to roughly 900 bytes. Use it for repeating\\nupdates where only the latest matters, never for messages that must arrive.","params":[{"name":"...","desc":"the type of each argument","lua_type":"GreenTeaType"}],"returns":[{"desc":"","lua_type":"Event<T...>"}],"function_type":"static","source":{"line":115,"path":"src/init.luau"}},{"name":"func","desc":"Creates a [Function], a typed `RemoteFunction` the client invokes on the server.\\n\\n```lua\\nbuyItemRemote = Sencha.func(gt.args(gt.string()), gt.returns(gt.boolean())),\\n```","params":[{"name":"args","desc":"`gt.args(...)`","lua_type":"GreenTeaArgs"},{"name":"returns","desc":"`gt.returns(...)`","lua_type":"GreenTeaReturns"}],"returns":[{"desc":"","lua_type":"Function<T..., R...>"}],"function_type":"static","source":{"line":131,"path":"src/init.luau"}},{"name":"eventSwitchboard","desc":"Creates an [EventSwitchboard]: one `RemoteEvent` that routes client calls to a server callback by port name.","params":[{"name":"...","desc":"the type of each argument after the port","lua_type":"GreenTeaType"}],"returns":[{"desc":"","lua_type":"EventSwitchboard<T...>"}],"function_type":"static","source":{"line":142,"path":"src/init.luau"}},{"name":"funcSwitchboard","desc":"Creates a [FunctionSwitchboard]: one `RemoteFunction` that routes client calls to a server callback by port\\nname.","params":[{"name":"args","desc":"`gt.args(...)`","lua_type":"GreenTeaArgs"},{"name":"returns","desc":"`gt.returns(...)`","lua_type":"GreenTeaReturns"}],"returns":[{"desc":"","lua_type":"FunctionSwitchboard<T..., R...>"}],"function_type":"static","source":{"line":155,"path":"src/init.luau"}},{"name":"savedSource","desc":"Creates a [SavedSource] for one store of saved player data. Create one per store in a shared module, then\\ncreate replicators from it with [SavedSource:replicator].\\n\\n```lua\\n-- ReplicatedStorage/PlayerDataSource.luau\\nreturn Sencha.savedSource(\\"PlayerData\\", PlayerDataTypes.PlayerData)\\n```","params":[{"name":"name","desc":"a name unique to this store","lua_type":"string"},{"name":"savedDataType","desc":"the built GreenTea type of the saved data","lua_type":"GreenTeaType"}],"returns":[{"desc":"","lua_type":"SavedSource<D>"}],"function_type":"static","source":{"line":189,"path":"src/init.luau"}},{"name":"define","desc":"Names and sets up every remote and replicator in `implementations` from its key, and returns the same table.\\nRemotes are created under `parent`, and each replicator\'s name is `parent:GetFullName()` plus its key, so the\\nsame module resolves to the same remotes and replicators on both sides.\\n\\nEach remote and replicator can only be defined once.","params":[{"name":"parent","desc":"usually `script`","lua_type":"Instance"},{"name":"implementations","desc":"a table of remotes and replicators","lua_type":"T"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"static","source":{"line":206,"path":"src/init.luau"}},{"name":"waitForReplicators","desc":"Yields until every replicator the server has defined has its first value on this client, including ones whose\\nmodules the client hasn\'t required yet. After this returns, `get()` is safe on every replicator.\\n\\nCall this once while loading, before starting systems that read replicated values. If this is still waiting after\\n5 seconds, a warning lists the replicators that don\'t have a value yet.","params":[],"returns":[],"function_type":"static","realm":["Client"],"yields":true,"source":{"line":224,"path":"src/init.luau"}}],"properties":[{"name":"temporaryReplicator","desc":"Creates replicators for state the server keeps in memory.\\n\\n- `temporaryReplicator.player` creates a [TemporaryPlayerReplicator]: one value per player, sent only to\\n  that player.\\n- `temporaryReplicator.global` creates a [TemporaryGlobalReplicator]: one value, sent to every player.\\n\\n```lua\\ncarriedOreReplicator = Sencha.temporaryReplicator.player(gt.number(), 0),\\nmeteorShowerReplicator = Sencha.temporaryReplicator.global(gt.boolean(), false),\\n```","lua_type":"{ player: (valueType, defaultValue, incrementalConfig?) -> TemporaryPlayerReplicator, global: (valueType, initialValue, incrementalConfig?) -> TemporaryGlobalReplicator }","source":{"line":172,"path":"src/init.luau"}}],"types":[{"name":"Disconnect","desc":"Every listener method returns a `Disconnect`, the cleanup function. Call it to stop listening. It\'s safe to call\\nmore than once, and can be handed to a cleanup library or returned from a React effect.","lua_type":"() -> ()","source":{"line":28,"path":"src/init.luau"}},{"name":"Limit","desc":"A rate limit for calls from clients, passed to `:rateLimit(...)` on any remote. Each player has their own budget.","fields":[{"name":"burst","lua_type":"number","desc":"calls a player can make at once; at least 1"},{"name":"perSecond","lua_type":"number","desc":"calls a player gets back each second; more than 0"}],"source":{"line":38,"path":"src/init.luau"}},{"name":"TemporaryIncrementalConfig","desc":"Makes a temporary replicator send patches with `applyIncrementalUpdate` instead of sending the whole value.","fields":[{"name":"patchType","lua_type":"GreenTeaType","desc":"the GreenTea type of a patch"},{"name":"apply","lua_type":"(value: T, patch: P) -> T","desc":"returns the value with the patch applied; runs on the server and the client"}],"source":{"line":48,"path":"src/init.luau"}},{"name":"SavedIncrementalConfig","desc":"Makes a saved replicator send patches instead of the whole value when the saved data changes.","fields":[{"name":"patchType","lua_type":"GreenTeaType","desc":"the GreenTea type of a patch"},{"name":"diff","lua_type":"(newValue: T, oldValue: T) -> P","desc":"returns a patch describing what changed; runs on the server"},{"name":"apply","lua_type":"(value: T, patch: P) -> T","desc":"returns the value with the patch applied; runs on the server and the client"}],"source":{"line":59,"path":"src/init.luau"}}],"name":"Sencha","desc":"Typed remotes and server-owned state for Roblox. Define remotes and replicators together in one shared module\\nwith [Sencha.define], and require it on the server and the client.\\n\\n```lua\\n-- ReplicatedStorage/CurrencyNetwork.luau\\nlocal Sencha = require(ReplicatedStorage.Packages.Sencha)\\nlocal gt = require(ReplicatedStorage.Packages.GreenTea)\\n\\nreturn Sencha.define(script, {\\n\\tbuyItemRemote = Sencha.func(gt.args(gt.string()), gt.returns(gt.boolean())),\\n\\tcoinsReplicator = Sencha.temporaryReplicator.player(gt.number(), 0),\\n})\\n```","source":{"line":87,"path":"src/init.luau"}}')}}]);